{"id":"22259696-a30d-4e6c-9176-0eefb98aad25","type":"https://serlo.org/editor","variant":"serlo-org","domainOrigin":"serlo.org","version":2,"editorVersion":"0.22.0","dateModified":"2025-02-26T18:21:36.504Z","document":{"plugin":"exercise","state":{"content":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Ein Cookie besitzt einen Durchmesser von 9 cm. Berechne den Umfang und Flächeninhalt. Runde deine Ergebnisse auf eine Nachkommastelle."}]}],"id":"d0ef9869-65fa-4805-a95a-f9f191343235"}],"id":"bb573aaa-6515-48ff-88ee-93b56bd3a752"},"solution":{"plugin":"solution","state":{"prerequisite":{"id":"36162","title":"Kreis"},"strategy":{"plugin":"text","state":[{"type":"p","children":[{}]}],"id":"cbeded82-1d33-40e5-aa7b-952797575031"},"steps":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Die Formel für den Kreisumfang ist:"}]}],"id":"111cd9ad-b4d5-4217-8f29-a4adc1a0cebd"},{"plugin":"text","state":[{"type":"math","src":"U_{\text{Kreis}} = 2\pi \cdot r","inline":false,"children":[{"text":""}]}],"id":"648fe11d-cdf2-4881-8923-7f7a29b37fe1"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Den Radius kannst du aus dem Durchmesser berechnen, wie folgt:"}]}],"id":"bac3a0ae-c1e4-4c87-8ad8-21ab8e49c950"},{"plugin":"text","state":[{"type":"math","src":"\begin{array}{rcl}
d = 2\cdot r \Rightarrow r &=& \dfrac{1}{2}d \\\\
r &=& \dfrac{1}{2} \cdot 9 \,\text{cm} = 4,5 \,\text{cm}
\end{array}","inline":false,"children":[{"text":""}]}],"id":"25aab9a2-67fd-4aa2-992a-10343447dd85"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Nun kannst du den Radius in die Formel einsetzen."}]},{"type":"math","src":"\begin{array}{rcl}
U_{\text{Kreis}} &=& 2\pi \cdot r \\
U_{\text{Kreis}} &=& 2\pi \cdot 4,5 \,\text{cm} \approx 28,3 \,\text{cm}^2
\end{array}","inline":false,"children":[{"text":""}]}],"id":"c47f544c-651a-43cf-9089-baa6be1f6bd0"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Als nächstes, musst du den Flächeninhalt des Cookies berechnen. Die allgemeine Formel für den Flächeninhalt ist:"}]}],"id":"d54ad693-cf9c-477f-a3f9-c410c0e89829"},{"plugin":"text","state":[{"type":"math","src":"A_{\text{Kreis}} = \pi \cdot r^2","inline":false,"children":[{"text":""}]}],"id":"a9bea103-9db5-4644-aa86-8b8d39eb911d"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Jetzt brauchst du nur noch den Radius einzusetzen."}]}],"id":"4c02bab5-149a-485c-aeff-ba94abb03633"},{"plugin":"text","state":[{"type":"math","src":"\begin{array}{rcl}
A_{\text{Kreis}} &=& \pi \cdot r^2 \\
A_{\text{Kreis}} &=& \pi \cdot (4,5 \,\text{cm})^2 \approx 63,6 \,\text{cm}^2
\end{array}","inline":false,"children":[{"text":""}]}],"id":"bc4ffe2a-5bad-46c4-a512-f08afc7b656d"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Daraus folgt, dass der Umkreis "},{"type":"math","src":"28,3 \,\text{cm}^2","inline":true,"children":[{"text":""}]},{"text":" und der Flächeninhalt "},{"type":"math","src":"63,6 \,\text{cm}^3","inline":true,"children":[{"text":""}]},{"text":" beträgt."}]}],"id":"6ff967f3-0d11-474b-9e34-caa1515def05"}],"id":"760a9c53-ff09-49ed-a2ab-7e0cc3cd76c3"}},"id":"45ab4eb6-6882-40b2-8faf-4c4fefff2868"}},"id":"59bc938a-b0a3-454a-922b-371a765e8a9c"}}
